pub fn hardcoded_all(dhatu_id: &str, lakara: &str, purusha: u8, vacana: u8) -> Option<Vec<String>> {
    let key = (dhatu_id, lakara, purusha, vacana);
    let idx = ENTRIES_ALL.binary_search_by(|(id, lak, p, v, _)| {
        ( *id, *lak, *p, *v).cmp(&(key.0, key.1, key.2, key.3))
    }).ok()?;
    let forms_str = ENTRIES_ALL[idx].4;
    Some(forms_str.split('|').map(|s| s.to_string()).collect())
}
